"use client";

import {
  Children,
  isValidElement,
  cloneElement,
  useRef,
  useState,
  useEffect,
  useLayoutEffect,
  useCallback,
  useMemo,
  createContext,
  useContext,
  forwardRef,
  type ReactElement,
  type ReactNode,
  type HTMLAttributes,
} from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Accordion as AccordionPrimitive } from "@base-ui/react/accordion";
import { ChevronRight } from "lucide-react";

import { cn } from "@/lib/utils";
import { spring } from "@/lib/springs";
import { fontWeights } from "@/lib/font-weight";
import { useProximityHover, type ItemRect } from "@/hooks/use-proximity-hover";

// SSR-safe layout effect (client components still server-render in Next).
const useIsoLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

// ─── Contexts ────────────────────────────────────────────────────────────────

interface AccordionContextValue {
  registerItem: (index: number, element: HTMLElement | null) => void;
  registerFullItem: (index: number, element: HTMLElement | null) => void;
  activeIndex: number | null;
  remeasure: () => void;
  openValues: Set<string>;
  openItemRects: Map<number, ItemRect>;
}

const AccordionContext = createContext<AccordionContextValue | null>(null);

function useAccordionContext() {
  const ctx = useContext(AccordionContext);
  if (!ctx) throw new Error("AccordionItem must be used within an Accordion");
  return ctx;
}

interface AccordionItemContextValue {
  index?: number;
  value: string;
  isOpen: boolean;
  triggerRef: React.MutableRefObject<HTMLDivElement | null>;
}

const AccordionItemContext = createContext<AccordionItemContextValue | null>(null);

function useAccordionItemContext() {
  const ctx = useContext(AccordionItemContext);
  if (!ctx) throw new Error("AccordionTrigger/AccordionContent must be used within an AccordionItem");
  return ctx;
}

// ─── Accordion ───────────────────────────────────────────────────────────────
// Every item shares one container: a background pill morphs between the item
// nearest the cursor and the currently open item(s) — the "proximity hover"
// principle (docs/design-system.md) applied to an accordion stack. Applies
// uniformly whether the accordion holds one item or many — a primitive looks
// and moves identically no matter which pattern embeds it.

type AccordionSingleProps = {
  type?: "single";
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};

type AccordionMultipleProps = {
  type: "multiple";
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
};

type AccordionProps = Omit<HTMLAttributes<HTMLDivElement>, "onFocus" | "onBlur"> & {
  children: ReactNode;
} & (AccordionSingleProps | AccordionMultipleProps);

const Accordion = forwardRef<HTMLDivElement, AccordionProps>((props, ref) => {
  const { children, type = "single", className, ...rest } = props;

  const containerRef = useRef<HTMLDivElement>(null);
  const fullItemElementsRef = useRef<Map<number, HTMLElement>>(new Map());
  const [openItemRects, setOpenItemRects] = useState<Map<number, ItemRect>>(new Map());
  const openItemRectsRef = useRef(openItemRects);

  const { activeIndex, setActiveIndex, itemRects, sessionRef, handlers, registerItem, measureItems } =
    useProximityHover(containerRef);

  const registerFullItem = useCallback((index: number, element: HTMLElement | null) => {
    if (element) fullItemElementsRef.current.set(index, element);
    else fullItemElementsRef.current.delete(index);
  }, []);

  const measureFullItems = useCallback(() => {
    if (!containerRef.current) return;
    const next = new Map<number, ItemRect>();
    fullItemElementsRef.current.forEach((el, idx) => {
      next.set(idx, {
        top: el.offsetTop,
        left: el.offsetLeft,
        width: el.offsetWidth,
        height: el.offsetHeight,
      });
    });
    // Skip the state update when nothing moved (mirrors the proximity hook's
    // measureItems guard) — this runs per animation frame via onUpdate, and
    // an unconditional set would invalidate the group context and re-render
    // every item even on no-op remeasures.
    const prev = openItemRectsRef.current;
    let changed = prev.size !== next.size;
    if (!changed) {
      for (const [idx, r] of next) {
        const p = prev.get(idx);
        if (!p || p.top !== r.top || p.left !== r.left || p.width !== r.width || p.height !== r.height) {
          changed = true;
          break;
        }
      }
    }
    if (!changed) return;
    openItemRectsRef.current = next;
    setOpenItemRects(next);
  }, []);

  const [internalSingleValue, setInternalSingleValue] = useState<string>(() =>
    type === "single" ? ((props as AccordionSingleProps).defaultValue ?? "") : "",
  );
  const [internalMultipleValue, setInternalMultipleValue] = useState<string[]>(() =>
    type === "multiple" ? ((props as AccordionMultipleProps).defaultValue ?? []) : [],
  );

  const openValuesList: string[] =
    type === "multiple"
      ? ((props as AccordionMultipleProps).value ?? internalMultipleValue)
      : (() => {
          const v = (props as AccordionSingleProps).value ?? internalSingleValue;
          return v ? [v] : [];
        })();

  // Keyed on the joined values so the Set (and the group context value below)
  // keeps a stable identity across re-renders where the open values haven't
  // actually changed.
  const openValuesKey = openValuesList.join(",");
  const openValues = useMemo(() => new Set(openValuesList), [openValuesKey]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    measureItems();
    measureFullItems();
  }, [measureItems, measureFullItems, children]);

  useEffect(() => {
    measureItems();
    measureFullItems();
  }, [measureItems, measureFullItems, openValuesKey]);

  const activeRect = activeIndex !== null ? itemRects[activeIndex] : null;
  const isHoveringNonOpen = activeIndex !== null && !openItemRects.has(activeIndex);

  const remeasure = useCallback(() => {
    measureItems();
    measureFullItems();
  }, [measureItems, measureFullItems]);

  // Translate the single/multiple public API → Base UI's Accordion API,
  // which always uses `value: string[]` plus a `multiple: boolean`. In
  // single mode the active value is wrapped in a single-element array.
  const baseValue: string[] =
    type === "multiple"
      ? ((props as AccordionMultipleProps).value ?? internalMultipleValue)
      : (() => {
          const v = (props as AccordionSingleProps).value ?? internalSingleValue;
          return v ? [v] : [];
        })();

  const baseOnValueChange = (next: string[]) => {
    if (type === "multiple") {
      const mp = props as AccordionMultipleProps;
      if (mp.onValueChange) mp.onValueChange(next);
      else setInternalMultipleValue(next);
    } else {
      const sp = props as AccordionSingleProps;
      if (sp.onValueChange) sp.onValueChange(next[0] ?? "");
      else setInternalSingleValue(next[0] ?? "");
    }
  };

  // Memoized: the group re-renders on every proximity-hover mousemove; a
  // fresh context object each time would re-render every item with it.
  const contextValue = useMemo<AccordionContextValue>(
    () => ({ registerItem, registerFullItem, activeIndex, remeasure, openValues, openItemRects }),
    [registerItem, registerFullItem, activeIndex, remeasure, openValues, openItemRects],
  );

  const { value: _value, defaultValue: _defaultValue, onValueChange: _onValueChange, ...htmlProps } = rest as Record<
    string,
    unknown
  >;

  // Auto-index items by position so callers never have to hand-thread an
  // `index` prop just to get proximity hover — pass one explicitly only to
  // override the child order (e.g. a fragment-wrapped item).
  const indexedChildren = Children.map(children, (child, position) => {
    if (!isValidElement(child)) return child;
    const el = child as ReactElement<{ index?: number }>;
    return el.props.index !== undefined ? el : cloneElement(el, { index: position });
  });

  return (
    <AccordionContext.Provider value={contextValue}>
      <AccordionPrimitive.Root
        value={baseValue}
        onValueChange={baseOnValueChange}
        multiple={type === "multiple"}
        ref={(node: HTMLDivElement | null) => {
          (containerRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
          if (typeof ref === "function") ref(node);
          else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
        }}
        data-slot="accordion"
        onMouseEnter={handlers.onMouseEnter}
        onMouseMove={(e: React.MouseEvent<HTMLDivElement>) => {
          // While the cursor is over an *open* item's content (below its
          // trigger), suspend proximity hover — the hover pill shouldn't
          // compete with the persistent open-item tint underneath it.
          const container = containerRef.current;
          if (container) {
            const cRect = container.getBoundingClientRect();
            const localY = e.clientY - cRect.top + container.scrollTop;
            for (const [idx, full] of openItemRects) {
              const trigger = itemRects[idx];
              if (!trigger) continue;
              const contentTop = trigger.top + trigger.height;
              const contentBottom = full.top + full.height;
              if (localY >= contentTop && localY <= contentBottom) {
                setActiveIndex(null);
                return;
              }
            }
          }
          handlers.onMouseMove(e);
        }}
        onMouseLeave={handlers.onMouseLeave}
        className={cn("relative flex w-full flex-col gap-0.5", className)}
        {...(htmlProps as Omit<HTMLAttributes<HTMLDivElement>, "defaultValue">)}
      >
        {/* Expanded item backgrounds — persistent, low-opacity tint under
            whichever item(s) are open. Geometry snaps (duration 0) so it
            hugs the item through its own height-spring animation; only
            opacity fades. */}
        <AnimatePresence>
          {[...openItemRects.entries()].map(([idx, rect]) => (
            <motion.div
              key={`expanded-${idx}`}
              className="pointer-events-none absolute rounded-lg bg-accent/20 dark:bg-accent/12"
              initial={{ top: rect.top, left: rect.left, width: rect.width, height: rect.height, opacity: 0 }}
              animate={{
                top: rect.top,
                left: rect.left,
                width: rect.width,
                height: rect.height,
                opacity: isHoveringNonOpen ? 0.7 : 1,
              }}
              exit={{ opacity: 0, transition: spring.moderate.exit }}
              transition={{
                top: { duration: 0 },
                left: { duration: 0 },
                width: { duration: 0 },
                height: { duration: 0 },
                opacity: { duration: 0.12 },
              }}
            />
          ))}
        </AnimatePresence>

        {/* Hover pill — tracks the item nearest the cursor. A faint
            foreground-tinted wash (not --accent), matching the reference's
            dedicated near-transparent hover color rather than a solid fill. */}
        <AnimatePresence>
          {activeRect && (
            <motion.div
              key={sessionRef.current}
              className="pointer-events-none absolute rounded-lg bg-foreground/[0.04] dark:bg-foreground/[0.06]"
              initial={{ opacity: 0, top: activeRect.top, left: activeRect.left, width: activeRect.width, height: activeRect.height }}
              animate={{ opacity: 1, top: activeRect.top, left: activeRect.left, width: activeRect.width, height: activeRect.height }}
              exit={{ opacity: 0, transition: spring.fast.exit }}
              transition={spring.fast.enter}
            />
          )}
        </AnimatePresence>

        {indexedChildren}
      </AccordionPrimitive.Root>
    </AccordionContext.Provider>
  );
});
Accordion.displayName = "Accordion";

// ─── AccordionItem ───────────────────────────────────────────────────────────

interface AccordionItemProps extends HTMLAttributes<HTMLDivElement> {
  value: string;
  /** Position for proximity hover — auto-assigned from child order; pass explicitly only to override it. */
  index?: number;
  disabled?: boolean;
  children: ReactNode;
}

const AccordionItem = forwardRef<HTMLDivElement, AccordionItemProps>(
  ({ value, index, disabled, children, className, ...props }, ref) => {
    const internalRef = useRef<HTMLDivElement>(null);
    const ctx = useAccordionContext();

    const isOpen = ctx.openValues.has(value);
    const triggerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
      if (index === undefined) return;
      ctx.registerItem(index, triggerRef.current);
      return () => ctx.registerItem(index, null);
    }, [index, ctx]);

    useEffect(() => {
      if (index === undefined) return;
      ctx.registerFullItem(index, isOpen ? internalRef.current : null);
      return () => ctx.registerFullItem(index, null);
    }, [index, ctx, isOpen]);

    return (
      <AccordionItemContext.Provider value={{ index, value, isOpen, triggerRef }}>
        <AccordionPrimitive.Item
          value={value}
          disabled={disabled}
          ref={(node: HTMLDivElement | null) => {
            (internalRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
          }}
          data-slot="accordion-item"
          data-proximity-index={index}
          className={className}
          {...props}
        >
          {children}
        </AccordionPrimitive.Item>
      </AccordionItemContext.Provider>
    );
  },
);
AccordionItem.displayName = "AccordionItem";

// ─── AccordionTrigger ────────────────────────────────────────────────────────

interface AccordionTriggerProps extends HTMLAttributes<HTMLButtonElement> {
  children: ReactNode;
}

const AccordionTrigger = forwardRef<HTMLButtonElement, AccordionTriggerProps>(
  ({ children, className, ...props }, ref) => {
    const ctx = useAccordionContext();
    const { index, isOpen, triggerRef } = useAccordionItemContext();

    const isActive = ctx.activeIndex === index;

    const triggerContent = (
      // Header renders as a <div>: Base UI's default <h3> would be more
      // semantic but the styles above key off it being a plain flex child.
      <AccordionPrimitive.Header render={<div />} data-slot="accordion-header">
        <AccordionPrimitive.Trigger
          ref={ref}
          data-slot="accordion-trigger"
          className={cn(
            "relative z-10 flex w-full cursor-pointer items-center gap-2.5 rounded-lg px-3 py-2 text-left outline-none select-none focus-visible:ring-2 focus-visible:ring-ring/50",
            className,
          )}
          {...props}
        >
          {/* Ghost-span: an invisible copy at the heaviest weight reserves
              the width so the visible copy's weight can animate without
              reflowing the row (docs/design-system.md "Ghost-span"). */}
          <span className="col-start-1 row-start-1 grid flex-1 text-left text-body">
            <span
              className="invisible col-start-1 row-start-1"
              style={{ fontVariationSettings: fontWeights.medium }}
              aria-hidden="true"
            >
              {children}
            </span>
            <span
              className={cn(
                "col-start-1 row-start-1 transition-colors duration-80",
                isOpen || isActive ? "text-foreground" : "text-muted-foreground",
              )}
              style={{ fontVariationSettings: isOpen ? fontWeights.medium : fontWeights.normal }}
            >
              {children}
            </span>
          </span>

          <motion.span
            className="inline-flex shrink-0 items-center justify-center"
            animate={{ rotate: isOpen ? 90 : 0 }}
            transition={spring.fast.enter}
          >
            <ChevronRight
              size={16}
              strokeWidth={isOpen || isActive ? 2 : 1.5}
              className={cn(
                "transition-colors duration-80",
                isOpen || isActive ? "text-foreground" : "text-muted-foreground",
              )}
            />
          </motion.span>
        </AccordionPrimitive.Trigger>
      </AccordionPrimitive.Header>
    );

    return <div ref={triggerRef}>{triggerContent}</div>;
  },
);
AccordionTrigger.displayName = "AccordionTrigger";

// ─── AccordionContent ────────────────────────────────────────────────────────

interface AccordionContentProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
}

const AccordionContent = forwardRef<HTMLDivElement, AccordionContentProps>(
  ({ children, className, ...props }, ref) => {
    const ctx = useAccordionContext();
    const { isOpen } = useAccordionItemContext();

    // The open height animates to a self-measured LAYOUT pixel value, not
    // `height: "auto"`: framer resolves an "auto" target by measuring the
    // element's *visual* (transformed) size, so under a scaled ancestor the
    // animation would overshoot and snap back at the end of every open.
    // offsetHeight and ResizeObserver are transform-immune.
    const innerRef = useRef<HTMLDivElement | null>(null);
    const roRef = useRef<ResizeObserver | null>(null);
    const [contentHeight, setContentHeight] = useState<number | null>(null);
    // Items open at mount must SNAP (duration 0) on their first pixel target,
    // not spring — framer would measure the spring's numeric start visually
    // and play a shrink. Items that open later spring normally.
    const needsSnap = useRef(isOpen);

    const measureRef = useCallback((el: HTMLDivElement | null) => {
      roRef.current?.disconnect();
      roRef.current = null;
      innerRef.current = el;
      if (!el) return;
      if (el.offsetHeight > 0) setContentHeight(el.offsetHeight);
      const ro = new ResizeObserver(() => {
        if (el.offsetHeight > 0) setContentHeight(el.offsetHeight);
      });
      ro.observe(el);
      roRef.current = ro;
    }, []);

    // Re-measure synchronously (pre-paint) when opening, so the spring's
    // target is the fresh layout height from its first frame.
    useIsoLayoutEffect(() => {
      if (isOpen && innerRef.current && innerRef.current.offsetHeight > 0) {
        setContentHeight(innerRef.current.offsetHeight);
      }
    }, [isOpen]);

    useEffect(() => {
      if (contentHeight !== null) needsSnap.current = false;
    }, [contentHeight]);

    // Whether the framer-motion height exit animation has fully finished.
    // Base UI's Panel would apply `hidden` the moment a controlled item
    // closes, which is `display: none` and would freeze the exit animation
    // mid-flight — so `hidden` is taken over below and only applied once the
    // exit has actually completed.
    const [exitComplete, setExitComplete] = useState(!isOpen);
    if (isOpen && exitComplete) {
      // Reset during render so the panel is un-hidden before the opening
      // animation's first paint.
      setExitComplete(false);
    }

    // Rendered through `<Panel keepMounted>` so the panel element persists
    // through the exit animation and the trigger ↔ panel ARIA contract stays
    // intact (role="region", aria-labelledby, the id Trigger's
    // aria-controls points to). The framer-motion height animation lives one
    // level down inside the persistent panel element.
    return (
      <AccordionPrimitive.Panel keepMounted hidden={!isOpen && exitComplete} data-slot="accordion-content">
        <motion.div
          ref={ref}
          className={cn("overflow-hidden", className)}
          initial={{ height: isOpen ? "auto" : 0 }}
          animate={{ height: isOpen ? (contentHeight ?? 0) : 0 }}
          // bounce: 0 — pure height looks better without overshoot (moderate is already bounce 0).
          transition={needsSnap.current ? { duration: 0 } : spring.moderate.enter}
          onUpdate={() => ctx.remeasure()}
          onAnimationComplete={() => {
            ctx.remeasure();
            if (!isOpen) setExitComplete(true);
          }}
          // AccordionContentProps is HTMLAttributes<HTMLDivElement>, but framer
          // motion's HTMLMotionProps types a few overlapping event handlers
          // (onDrag, onAnimationStart, ...) differently — cast to sidestep the
          // structural mismatch rather than hand-filter every conflicting key.
          {...(props as Record<string, unknown>)}
        >
          <div ref={measureRef} className="px-3 pt-1 pb-3 text-caption text-muted-foreground">
            {children}
          </div>
        </motion.div>
      </AccordionPrimitive.Panel>
    );
  },
);
AccordionContent.displayName = "AccordionContent";

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };
export default Accordion;

"use client";

import {
  useRef,
  useState,
  useCallback,
  useEffect,
  type Dispatch,
  type RefObject,
  type SetStateAction,
} from "react";

export interface ItemRect {
  top: number;
  height: number;
  left: number;
  width: number;
}

interface UseProximityHoverOptions {
  /**
   * Which direction to resolve the nearest item along.
   *   "y"  — vertical lists (default): closest by top/height
   *   "x"  — horizontal strips: closest by left/width
   *   "xy" — 2-D grids: closest card across both rows AND columns,
   *          measured by Euclidean distance to each item's center
   */
  axis?: "x" | "y" | "xy";
}

interface UseProximityHoverReturn {
  activeIndex: number | null;
  setActiveIndex: Dispatch<SetStateAction<number | null>>;
  itemRects: ItemRect[];
  /**
   * True once every registered item has been measured and no remeasure is
   * pending, i.e. `itemRects` describes the current item set. Gate absolutely
   * positioned overlays on it: an overlay that mounts against a rect a later
   * pass still corrects animates from the wrong place to the right one, which
   * reads as the highlight sliding in from another row.
   */
  isMeasured: boolean;
  sessionRef: RefObject<number>;
  handlers: {
    onMouseMove: (e: React.MouseEvent) => void;
    onMouseEnter: () => void;
    onMouseLeave: () => void;
  };
  registerItem: (index: number, element: HTMLElement | null) => void;
  /**
   * Invalidates the published rects and runs the hook's coalesced measurement
   * pass again, holding `isMeasured` false until it settles. Reach for it when
   * something other than item registration invalidates layout — a popup that
   * stays mounted between opens keeps its items registered, so nothing else
   * would notice that its rects were taken while it was hidden.
   */
  remeasure: () => void;
  measureItems: () => void;
}

/**
 * How many frames the coalesced remeasure retries while the registered items
 * still have no layout box. A popup can be in the DOM one frame before it is
 * laid out; retrying beats publishing zeroed rects, and the cap keeps a list
 * that stays hidden for good from spinning frames forever.
 */
const measurementAttempts = 3;

/**
 * Drives "proximity hover" (docs/design-system.md): in an interactive
 * list/grid, highlight the item nearest the cursor before the user clicks,
 * rather than only lighting up on direct :hover. Consumers register their
 * item elements by index and get back the nearest index plus its rect, to
 * position a moving highlight behind the list.
 */
export function useProximityHover<T extends HTMLElement>(
  containerRef: RefObject<T | null>,
  options: UseProximityHoverOptions = {},
): UseProximityHoverReturn {
  const { axis = "y" } = options;
  const itemsRef = useRef(new Map<number, HTMLElement>());
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const [itemRects, setItemRects] = useState<ItemRect[]>([]);
  const [isMeasured, setIsMeasured] = useState(false);
  const itemRectsRef = useRef<ItemRect[]>([]);
  const sessionRef = useRef(0);
  const rafIdRef = useRef<number | null>(null);
  const remeasureRafIdRef = useRef<number | null>(null);

  /**
   * Publishes a rect for every registered item. Returns false when the
   * measurement could not be completed (no container, or an item without a
   * layout box) — nothing is published in that case, so the last complete
   * measurement stands instead of being overwritten with zeroes.
   */
  const runMeasurement = useCallback(() => {
    const container = containerRef.current;
    if (!container) return false;
    const rects: ItemRect[] = [];
    let everyItemHasLayout = true;
    itemsRef.current.forEach((element, index) => {
      // An element inside a display:none / not-yet-laid-out popup has no
      // offsetParent and reports every offset as 0. Publishing that would pin
      // overlays to the top of the list, so treat the whole pass as
      // incomplete. A boxless element is the only case: `position: fixed`
      // items also have no offsetParent but do have a size.
      const hasLayoutBox =
        element.offsetParent !== null || element.offsetWidth > 0 || element.offsetHeight > 0;
      if (!hasLayoutBox) {
        everyItemHasLayout = false;
        return;
      }
      // Use offset* instead of getBoundingClientRect so measurements are
      // unaffected by CSS transforms (e.g. scaleY animation on the parent
      // motion.div). offsetTop/offsetLeft are layout values relative to the
      // offsetParent (the scroll container), matching the coordinate space
      // used by `position: absolute` children.
      rects[index] = {
        top: element.offsetTop,
        height: element.offsetHeight,
        left: element.offsetLeft,
        width: element.offsetWidth,
      };
    });
    if (!everyItemHasLayout) return false;
    // Skip the state update when nothing moved (a cheap top/left/width/height
    // compare) so redundant remeasures don't churn re-renders.
    const prev = itemRectsRef.current;
    let changed = prev.length !== rects.length;
    for (let i = 0; !changed && i < rects.length; i++) {
      const p = prev[i];
      const r = rects[i];
      if (p === r) continue; // both undefined (sparse slot)
      changed = !p || !r || p.top !== r.top || p.left !== r.left || p.width !== r.width || p.height !== r.height;
    }
    if (changed) {
      itemRectsRef.current = rects;
      setItemRects(rects);
    }
    return true;
  }, [containerRef]);

  const measureItems = useCallback(() => {
    runMeasurement();
  }, [runMeasurement]);

  /**
   * The hook's single measurement pass: coalesces every trigger (item
   * registration, container resize) into one remeasure on the next frame and
   * is the only place readiness is reported, so `isMeasured` can never turn
   * true while another pass is still queued.
   */
  const scheduleMeasurement = useCallback(
    (attemptsLeft: number) => {
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current);
      }
      remeasureRafIdRef.current = requestAnimationFrame(() => {
        remeasureRafIdRef.current = null;
        if (runMeasurement()) {
          setIsMeasured(true);
        } else if (attemptsLeft > 1) {
          scheduleMeasurement(attemptsLeft - 1);
        }
      });
    },
    [runMeasurement],
  );

  const remeasure = useCallback(() => {
    // Readiness drops first: until the pass below settles, the published rects
    // may not describe what is on screen, and an overlay positioned from them
    // would be corrected after mounting — which animates as a slide.
    setIsMeasured(false);
    scheduleMeasurement(measurementAttempts);
  }, [scheduleMeasurement]);

  const registerItem = useCallback(
    (index: number, element: HTMLElement | null) => {
      if (element) {
        itemsRef.current.set(index, element);
      } else {
        itemsRef.current.delete(index);
      }
      // Coalesce rapid register/unregister calls (e.g. when an AnimatePresence
      // remounts a list of rows) into a single remeasure on the next frame, so
      // consumers don't have to manually call measureItems after the
      // container's children swap.
      remeasure();
    },
    [remeasure],
  );

  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }

      rafIdRef.current = requestAnimationFrame(() => {
        rafIdRef.current = null;
        const container = containerRef.current;
        if (!container) return;

        const containerRect = container.getBoundingClientRect();

        // ── 2-D grid path ──────────────────────────────────────────
        // When items wrap into rows and columns, a single-axis nearest pick
        // can't tell which card the cursor is closest to. Resolve by
        // Euclidean distance to each item's center, and prefer any item the
        // cursor is actually inside (point-in-rect).
        if (axis === "xy") {
          let closestIndex: number | null = null;
          let closestDistance = Infinity;
          let containingIndex: number | null = null;

          const rects = itemRectsRef.current;
          const scrollX = container.scrollLeft;
          const scrollY = container.scrollTop;
          const borderX = container.clientLeft;
          const borderY = container.clientTop;
          // Map layout coords into visual/viewport space, accounting for any
          // cumulative ancestor transform: scale (see the single-axis note
          // below). X and Y scale independently.
          const scaleX = container.offsetWidth > 0 ? containerRect.width / container.offsetWidth : 1;
          const scaleY = container.offsetHeight > 0 ? containerRect.height / container.offsetHeight : 1;

          for (let index = 0; index < rects.length; index++) {
            const r = rects[index];
            if (!r) continue;

            const left = containerRect.left + (borderX + r.left - scrollX) * scaleX;
            const top = containerRect.top + (borderY + r.top - scrollY) * scaleY;
            const width = r.width * scaleX;
            const height = r.height * scaleY;

            if (mouseX >= left && mouseX <= left + width && mouseY >= top && mouseY <= top + height) {
              containingIndex = index;
            }

            const dx = mouseX - (left + width / 2);
            const dy = mouseY - (top + height / 2);
            const distance = Math.hypot(dx, dy);

            if (distance < closestDistance) {
              closestDistance = distance;
              closestIndex = index;
            }
          }

          setActiveIndex(containingIndex ?? closestIndex);
          return;
        }

        const mousePos = axis === "x" ? mouseX : mouseY;

        let closestIndex: number | null = null;
        let closestDistance = Infinity;
        let containingIndex: number | null = null;

        const rects = itemRectsRef.current;
        // Convert content-relative rects to viewport coords using live scroll.
        const scrollOffset = axis === "x" ? container.scrollLeft : container.scrollTop;
        const borderOffset = axis === "x" ? container.clientLeft : container.clientTop;
        const containerEdge = axis === "x" ? containerRect.left : containerRect.top;
        // Item rects are layout values (offset*); the container's bounding
        // rect reflects any cumulative ancestor transform: scale. Compute the
        // scale factor so we can map layout coords into the same visual
        // viewport space the mouse cursor lives in.
        const layoutSize = axis === "x" ? container.offsetWidth : container.offsetHeight;
        const visualSize = axis === "x" ? containerRect.width : containerRect.height;
        const scale = layoutSize > 0 ? visualSize / layoutSize : 1;

        for (let index = 0; index < rects.length; index++) {
          const r = rects[index];
          if (!r) continue;

          const contentPos = axis === "x" ? r.left : r.top;
          const itemStart = containerEdge + (borderOffset + contentPos - scrollOffset) * scale;
          const itemSize = (axis === "x" ? r.width : r.height) * scale;
          const itemEnd = itemStart + itemSize;

          if (mousePos >= itemStart && mousePos <= itemEnd) {
            containingIndex = index;
          }

          const itemCenter = itemStart + itemSize / 2;
          const distance = Math.abs(mousePos - itemCenter);

          if (distance < closestDistance) {
            closestDistance = distance;
            closestIndex = index;
          }
        }

        setActiveIndex(containingIndex ?? closestIndex);
      });
    },
    [axis, containerRef],
  );

  const handleMouseEnter = useCallback(() => {
    sessionRef.current += 1;
  }, []);

  const handleMouseLeave = useCallback(() => {
    if (rafIdRef.current !== null) {
      cancelAnimationFrame(rafIdRef.current);
      rafIdRef.current = null;
    }
    setActiveIndex(null);
  }, []);

  // Remeasure when the container resizes — a reflow moves items even though
  // the registered set is unchanged, which would otherwise leave itemRects
  // stale. Coalesced through the same rAF as register/unregister. Readiness
  // is deliberately not dropped: the item set is unchanged, so the published
  // rects stay usable, and hiding overlays on every reflow would flicker them.
  useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(() => scheduleMeasurement(measurementAttempts));
    ro.observe(container);
    return () => ro.disconnect();
  }, [containerRef, scheduleMeasurement]);

  useEffect(() => {
    return () => {
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }
      if (remeasureRafIdRef.current !== null) {
        cancelAnimationFrame(remeasureRafIdRef.current);
      }
    };
  }, []);

  return {
    activeIndex,
    setActiveIndex,
    itemRects,
    isMeasured,
    sessionRef,
    handlers: {
      onMouseMove: handleMouseMove,
      onMouseEnter: handleMouseEnter,
      onMouseLeave: handleMouseLeave,
    },
    registerItem,
    remeasure,
    measureItems,
  };
}

import type { Transition } from "framer-motion";

/**
 * Motion tokens — see docs/design-system.md "Motion & interaction
 * principles". Three tiers, each an enter spring paired with a faster,
 * bounce-free exit tween. Never hand-write a duration/transition inline —
 * import the tier that matches how big the thing moving is.
 */

interface SpringTier {
  /** Enter transition — spring, responds naturally to interruption. */
  enter: Transition;
  /** Exit transition — plain tween, one notch quicker, no bounce. */
  exit: Transition;
}

export const spring = {
  /** Hover, focus rings, fades, tooltips, selection indicators. */
  fast: {
    enter: { type: "spring", duration: 0.08, bounce: 0 },
    exit: { duration: 0.06, ease: "easeOut" },
  },
  /**
   * Short travel / small expansion (dropdown & tab indicators, switch
   * thumb, accordions) and panels that must land exactly (mobile drawer,
   * selection merge/split).
   */
  moderate: {
    enter: { type: "spring", duration: 0.16, bounce: 0 },
    exit: { duration: 0.12, ease: "easeOut" },
  },
  /** Large surfaces: dialogs, side panels, stepped flows. */
  slow: {
    enter: { type: "spring", duration: 0.24, bounce: 0.12 },
    exit: { duration: 0.16, ease: "easeOut" },
  },
} satisfies Record<"fast" | "moderate" | "slow", SpringTier>;

/**
 * Geist Sans weight tokens for `fontVariationSettings` — see
 * docs/design-system.md "Ghost-span for animated font-weight". Geist is a
 * variable font (loaded without a fixed `weight` in layout.tsx, so
 * next/font/google serves the full `wght` axis) but has no `opsz` axis, so
 * unlike some variable fonts there's no optical-size compensation to pair
 * each weight with.
 */
export const fontWeights = {
  normal: "'wght' 400",
  medium: "'wght' 500",
} as const;
